import React, { useEffect, useMemo, useState } from 'react';
import Breadcrumbs from '@mui/material/Breadcrumbs';
import { Link, useLocation, useParams } from 'react-router-dom';
import Typography from '@mui/material/Typography';
import { Button, Col, Row } from 'react-bootstrap';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import TableCell from '@mui/material/TableCell';
import TableBody from '@mui/material/TableBody';
import Table from '@mui/material/Table';
import Paper from '@mui/material/Paper';
import FormControlLabel from '@mui/material/FormControlLabel';
import TextField from '@mui/material/TextField';
import FormControl from '@mui/material/FormControl';
import FormGroup from '@mui/material/FormGroup';
import Checkbox from '@mui/material/Checkbox';
import HomeBreadcrumbs from '../../Assets/Img/home-breadcrumbs.svg';
import { Radio, RadioGroup } from '@mui/material';
import CheckIcon from '../../Assets/Img/check-green.svg';
import {
  bulkUpdateBookingGuest,
  deleteETicketGuestList,
  deleteReactiveBookingGuest,
  getBookingGuestListData,
  rebuildETicketGuestList,
  recreateETicketGuestList,
} from 'store/reducers/Booking/bookingGuest.slice';
import { useDispatch, useSelector } from 'react-redux';
import CrossIcon from '../../Assets/Img/cross-red.svg';
import Loader from 'Components/Common/Loader';
import DeletePopupModal from 'Components/Common/DeletePopupModal';
import AddGuestPopup from './AddGuestPopup';
import EditIcon from '../../Assets/Img/edit.svg';

export default function Guestlist() {
  const { bookingId } = useParams();
  const dispatch = useDispatch();

  const {
    bookingGuestList,
    isBookingGuestUpdated,
    isBulkGuestUpdated,
    bookingGuestLoading,
    isGuestlistUpdateData,
    guestlistUpdatedNewData,
  } = useSelector(({ bookingGuest }) => bookingGuest);

  const [addGuestPopup, setAddGuestPopup] = useState(false);

  const [rebuildPopup, setRebuildPopup] = useState(false);
  const [rebuildId, setRebuildId] = useState('');

  const [deleteETicketPopup, setDeleteETicketPopup] = useState(false);
  const [deleteETicketId, setDeleteETicketdId] = useState('');

  const [deleteGuestPopup, setDeleteGuestPopup] = useState(false);
  const [deleteGuestId, setDeleteGuestdId] = useState('');

  const [recreatePopup, setRecreatedPopup] = useState(false);

  const [deleteToggle, setDeleteToggle] = useState(false);
  const [enabledEticket, setEnabledEticket] = useState(false);
  const [guestList, setGuestList] = useState([]);
  const [deleteGuestList, setDeletedGuestList] = useState([]);
  const [loader, setLoader] = useState(false);
  const [editUser, setEditUser] = useState(null);
  const OpenAddGuest = () => {
    setAddGuestPopup(true);
  };
  const CloseAddGuest = () => {
    setAddGuestPopup(false);
    setEditUser(null);
  };

  const { state } = useLocation();

  useEffect(() => {
    if (bookingId) {
      dispatch(getBookingGuestListData(bookingId));
    }
  }, [bookingId]);

  useEffect(() => {
    if (isGuestlistUpdateData) {
      dispatch(getBookingGuestListData(bookingId));
    }
  }, [isGuestlistUpdateData]);

  useEffect(() => {
    if ((isBulkGuestUpdated || isBookingGuestUpdated) && bookingId) {
      dispatch(getBookingGuestListData(bookingId));
    }
  }, [isBulkGuestUpdated, isBookingGuestUpdated]);
  useEffect(() => {
    if (bookingGuestList?.length > 0) {
      let deletedGuest = bookingGuestList.filter(data => data.deleted);
      let GuestList = bookingGuestList.filter(data => data.deleted === false);
      setGuestList(GuestList);
      setDeletedGuestList(deletedGuest);
    }
  }, [bookingGuestList]);

  const memoizedGuestList = useMemo(() => {
    return bookingGuestList?.filter(data => data.deleted === false) || [];
  }, [bookingGuestList]);

  const handleChange = (list, listName, data, name, value) => {
    let dummyList = list?.map(item => {
      if (data._id === item._id) {
        return { ...item, [name]: value };
      }
      return item;
    });
    if (listName === 'Guest') {
      setGuestList(dummyList);
    } else {
      setDeletedGuestList(dummyList);
    }
  };

  const onGetListRequirementCheck = (list, listName, data, item, e) => {
    let dummyList = list?.map(iitem => {
      if (data._id === iitem._id) {
        let tempListData = iitem.requirements.map(item1 => {
          if (item1.title === item.title) {
            return {
              ...item1,
              is_selected: e.target.checked,
            };
          }
          return item1;
        });
        return { ...iitem, requirements: tempListData };
      }
      return iitem;
    });
    if (listName === 'Guest') {
      setGuestList(dummyList);
    } else {
      setDeletedGuestList(dummyList);
    }
  };

  //rebuild eticket
  const OpenRebuidETicket = data => {
    setRebuildId(data);
    setRebuildPopup(true);
  };

  const CloseRebuidETicket = () => {
    setRebuildPopup(false);
  };

  const rebuildETicketListData = () => {
    dispatch(
      rebuildETicketGuestList({
        guest_id: rebuildId._id,
        booking_id: bookingId,
      }),
    );
  };

  // delete eticket
  const OpenDeleteETicket = data => {
    setDeleteETicketdId(data);
    setDeleteETicketPopup(true);
  };

  const CloseDeleteETicket = () => {
    setDeleteETicketPopup(false);
  };

  const deleteEticketListData = () => {
    dispatch(deleteETicketGuestList(deleteETicketId._id));
  };

  // delete guest
  const OpenGuestDelete = data => {
    setDeleteGuestdId(data);
    setDeleteGuestPopup(true);
  };

  const CloseGuestDelete = () => {
    setDeleteGuestPopup(false);
  };

  const deleteGuestListData = () => {
    let obj = { deleted: !deleteGuestId.deleted };
    dispatch(
      deleteReactiveBookingGuest({
        guest_id: deleteGuestId._id,
        booking_id: bookingId,
        obj,
      }),
    );
  };

  //reset and reacreate eticket
  const OpenResetRecreateETicket = () => {
    setRecreatedPopup(true);
  };

  const CloseResetRecreateETicket = () => {
    setRecreatedPopup(false);
  };

  const resetRecreateETicketEticket = () => {
    dispatch(
      recreateETicketGuestList({
        booking_id: bookingId,
      }),
    );
  };

  // const compareArraysOfObjects = (oldArray, changedArray, key) => {
  //   let changes = [];

  //   // Compare changedArray to oldArray (detect additions and modifications)
  //   changedArray.forEach(newObj => {
  //     const oldObj = oldArray.find(obj => obj['_id'] === newObj['_id']); // Find the object by unique key (id or something unique)

  //     if (!oldObj) {
  //       // If the object is not found in the old array, it's an addition
  //       changes.push(newObj);
  //     } else {
  //       // If the object exists, compare its properties
  //       const isModified = Object.keys(newObj).some(
  //         prop => newObj[prop] !== oldObj[prop],
  //       );
  //       if (isModified) {
  //         // If any property has changed, consider it a modification
  //         changes.push(newObj);
  //       }
  //     }
  //   });

  //   return changes;
  // };

  // const sendApiRequestsInChunks = allRecords => {
  //   // Function to split array into chunks of 50
  //   const chunkSize = 50;
  //   const chunks = [];
  //   for (let i = 0; i < allRecords.length; i += chunkSize) {
  //     chunks.push(allRecords.slice(i, i + chunkSize));
  //   }
  //   return chunks;
  // };

  // const handUpdateGuest = async () => {
  //   const guestData = compareArraysOfObjects(bookingGuestList, [
  //     ...guestList,
  //     ...deleteGuestList,
  //   ]);
  //   const chunks = sendApiRequestsInChunks(guestData);

  //   setLoader(true);

  //   const apiCalls = chunks.map(chunk => {
  //     const guest = {
  //       guests: chunk,
  //     };
  //     return dispatch(
  //       bulkUpdateBookingGuest({
  //         _id: bookingId,
  //         bookingGuest: guest,
  //       }),
  //     );
  //   });
  //   await Promise.all(apiCalls);
  //   setLoader(false);
  // };
  return (
    <div className="inner_wrapper">
      {(bookingGuestLoading || loader) && <Loader />}
      <div className="guest_list_wrap">
        <div className="breadcrumb_wrap">
          <Breadcrumbs aria-label="breadcrumb">
            <Link to="/">
              <img src={HomeBreadcrumbs} alt="Home Icon" />
            </Link>
            <Link to="/bookings">Bookings</Link>
            <Typography>Edit booking</Typography>
            <Typography>Guestlist</Typography>
          </Breadcrumbs>
        </div>
        <div className="page_title">
          <Row className="align-items-center">
            <Col xs={3}>
              <h1>Guestlist</h1>
            </Col>
            <Col xs={9}>
              <div className="text-end">
                <Link
                  to={`/edit-bookings/${bookingId}`}
                  className="btn_border small"
                >
                  Back to Booking
                </Link>
              </div>
            </Col>
          </Row>
        </div>
        {isGuestlistUpdateData && guestlistUpdatedNewData?.pdf_tickets_file && (
          <div className="view_invoice_wrapper">
            <Link
              to={guestlistUpdatedNewData?.pdf_tickets_file}
              target="_blank"
            >
              There is a new eTicket available - click here to view the eTicket
            </Link>
          </div>
        )}
        <div className="guest-list_top_wrap bg_white_box p-3 mb-3">
          <div className="d-flex justify-content-between align-items-center mb-2">
            <h4 className="m-0">+Dietary Requirements</h4>
            <button
              type="button"
              className="btn_primary small"
              onClick={OpenAddGuest}
            >
              Add Guest
            </button>
          </div>
          {bookingGuestList?.length > 0 && (
            <p>
              Places Confirmed
              <span className="btn_primary small mx-2">
                {state?.confirmed_places}
              </span>
              Provisional Places
              <span className="btn_primary small mx-2">
                {state?.provisional_places}
              </span>
            </p>
          )}
        </div>
        {memoizedGuestList?.length > 0 ? (
          <>
            <div className="guest_list_table">
              <div className="table_main_Wrapper pages_active_table mb-3">
                <TableContainer component={Paper}>
                  <Table sx={{ minWidth: 650 }} aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>Manager</TableCell>
                        <TableCell>First Name</TableCell>
                        <TableCell>Surname</TableCell>
                        <TableCell>Email</TableCell>
                        <TableCell>Requirements</TableCell>
                        <TableCell>Attendance</TableCell>
                        <TableCell>Tkt #</TableCell>
                        <TableCell sx={{ width: '10%' }}>Action</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {memoizedGuestList.map(data => {
                        return (
                          <TableRow key={data._id}>
                            <TableCell>
                              {data?.is_manager ? (
                                <img src={CheckIcon} alt="Check Icon" />
                              ) : (
                                <img src={CrossIcon} alt="Check Icon" />
                              )}
                            </TableCell>
                            <TableCell>
                              <FormControl
                                fullWidth
                                className="main_input_wrap"
                              >
                                <span>{data.first_name}</span>
                              </FormControl>
                            </TableCell>
                            <TableCell>
                              <FormControl
                                fullWidth
                                className="main_input_wrap"
                              >
                                <span>{data.last_name}</span>
                              </FormControl>
                            </TableCell>
                            <TableCell>
                              <FormControl
                                fullWidth
                                className="main_input_wrap"
                              >
                                <span>{data.email}</span>
                              </FormControl>
                            </TableCell>
                            <TableCell>
                              <div className="guest_table_check">
                                <ul>
                                  {data.requirements?.map(item => {
                                    return (
                                      <li key={item?._id}>
                                        <div className="form-group checkbox_wrap mb-2">
                                          <FormGroup>
                                            <FormControlLabel
                                              className={
                                                item?.title?.toLowerCase() ===
                                                'wheelchair user'
                                                  ? 'text_primary'
                                                  : ''
                                              }
                                              control={<Checkbox />}
                                              label={item.title}
                                              checked={item.is_selected}
                                              disabled
                                            />
                                          </FormGroup>
                                        </div>
                                      </li>
                                    );
                                  })}
                                </ul>
                              </div>
                            </TableCell>
                            <TableCell>
                              <div className="guest_table_radio">
                                <FormControl>
                                  <RadioGroup
                                    row
                                    aria-labelledby="internal-label"
                                    name="radio-buttons-group"
                                    value={data.is_attending}
                                    disabled
                                    className="custom_radio"
                                  >
                                    <FormControlLabel
                                      value={0}
                                      control={<Radio />}
                                      label="Attending"
                                      className="w-100"
                                    />
                                    <FormControlLabel
                                      value={1}
                                      control={<Radio />}
                                      label="Not Attending"
                                      className="w-100"
                                    />
                                    <FormControlLabel
                                      value={2}
                                      control={<Radio />}
                                      label="Don't Know"
                                      className="w-100"
                                    />
                                  </RadioGroup>
                                </FormControl>
                              </div>
                            </TableCell>
                            <TableCell>
                              <FormControl
                                fullWidth
                                className="main_input_wrap"
                              >
                                <span>{data.etickets_num}</span>
                              </FormControl>
                            </TableCell>
                            <TableCell>
                              <ul className="action_wrap d-flex align-items-center justify-content-between">
                                <li
                                  className="cursor-pointer"
                                  onClick={() => {
                                    setEditUser(data);
                                    setAddGuestPopup(true);
                                  }}
                                >
                                  <img src={EditIcon} alt="Edit Icon" />
                                </li>
                                {data.deleted === false && (
                                  <li className="p-0">
                                    <button
                                      type="button"
                                      className="btn_danger"
                                      onClick={() => OpenGuestDelete(data)}
                                    >
                                      Delete
                                    </button>
                                  </li>
                                )}
                              </ul>
                            </TableCell>
                          </TableRow>
                        );
                      })}

                      <TableRow className="full_row">
                        <TableCell>
                          <span
                            className="text-decoration-underline custom_text_hover"
                            onClick={() => {
                              setDeleteToggle(!deleteToggle);
                            }}
                          >
                            DELETED / UNLINKED GUESTS
                          </span>
                        </TableCell>
                      </TableRow>
                      {deleteToggle &&
                        deleteGuestList.map(data => {
                          return (
                            <TableRow key={data._id} className="bg_highlight">
                              <TableCell>
                                {data?.is_manager ? (
                                  <img src={CheckIcon} alt="Check Icon" />
                                ) : (
                                  <img src={CrossIcon} alt="Check Icon" />
                                )}
                              </TableCell>
                              <TableCell>
                                <FormControl
                                  fullWidth
                                  className="main_input_wrap"
                                >
                                  <TextField
                                    id="firstName"
                                    type="text"
                                    variant="outlined"
                                    value={data.first_name}
                                    onChange={e => {
                                      handleChange(
                                        deleteGuestList,
                                        'deleteGuest',
                                        data,
                                        'first_name',
                                        e.target.value,
                                      );
                                    }}
                                  />
                                </FormControl>
                              </TableCell>
                              <TableCell>
                                <FormControl
                                  fullWidth
                                  className="main_input_wrap"
                                >
                                  <TextField
                                    id="surName"
                                    type="text"
                                    variant="outlined"
                                    value={data.last_name}
                                    onChange={e => {
                                      handleChange(
                                        deleteGuestList,
                                        'deleteGuest',
                                        data,
                                        'last_name',
                                        e.target.value,
                                      );
                                    }}
                                  />
                                </FormControl>
                              </TableCell>
                              <TableCell>
                                <FormControl
                                  fullWidth
                                  className="main_input_wrap"
                                >
                                  <TextField
                                    id="email"
                                    type="text"
                                    variant="outlined"
                                    value={data.email}
                                    onChange={e => {
                                      handleChange(
                                        deleteGuestList,
                                        'deleteGuest',
                                        data,
                                        'email',
                                        e.target.value,
                                      );
                                    }}
                                  />
                                </FormControl>
                              </TableCell>
                              <TableCell>
                                <div className="guest_table_check">
                                  <ul>
                                    {data.requirements?.map(item => {
                                      return (
                                        <li key={item?._id}>
                                          <div className="form-group checkbox_wrap mb-2">
                                            <FormGroup>
                                              <FormControlLabel
                                                className={
                                                  item?.title?.toLowerCase() ===
                                                  'wheelchair user'
                                                    ? 'text_primary'
                                                    : ''
                                                }
                                                control={<Checkbox />}
                                                label={item.title}
                                                checked={item.is_selected}
                                                onChange={e => {
                                                  onGetListRequirementCheck(
                                                    deleteGuestList,
                                                    'deleteGuest',
                                                    data,
                                                    item,
                                                    e,
                                                  );
                                                }}
                                              />
                                            </FormGroup>
                                          </div>
                                        </li>
                                      );
                                    })}
                                  </ul>
                                </div>
                              </TableCell>
                              <TableCell>
                                <div className="guest_table_radio">
                                  <FormControl>
                                    <RadioGroup
                                      row
                                      aria-labelledby="internal-label"
                                      name="radio-buttons-group"
                                      value={data.is_attending}
                                      onChange={e => {
                                        handleChange(
                                          deleteGuestList,
                                          'deleteGuest',
                                          data,
                                          'is_attending',
                                          Number(e.target.value),
                                        );
                                      }}
                                      className="custom_radio"
                                    >
                                      <FormControlLabel
                                        value={0}
                                        control={<Radio />}
                                        label="Attending"
                                        className="w-100"
                                      />
                                      <FormControlLabel
                                        value={1}
                                        control={<Radio />}
                                        label="Not Attending"
                                        className="w-100"
                                      />
                                      <FormControlLabel
                                        value={2}
                                        control={<Radio />}
                                        label="Don't Know"
                                        className="w-100"
                                      />
                                    </RadioGroup>
                                  </FormControl>
                                </div>
                              </TableCell>
                              <TableCell>
                                <ul className="action_wrap">
                                  <li className="p-0">
                                    <button
                                      type="button"
                                      className="btn_danger"
                                      onClick={() => OpenGuestDelete(data)}
                                    >
                                      Re-active
                                    </button>
                                  </li>
                                </ul>
                              </TableCell>
                            </TableRow>
                          );
                        })}
                    </TableBody>
                  </Table>
                </TableContainer>
                {/* <div className="d-flex justify-content-between align-items-center mb-2">
                  <h4 className="m-0"></h4>
                  <Button
                    className="btn_border small mx-2"
                    onClick={handUpdateGuest}
                  >
                    Update Guests
                  </Button>
                </div> */}
                {/* <Button
                  className="btn_border small mx-2"
                  onClick={e => {
                    let guest = { guests: [...guestList, ...deleteGuestList] };
                    dispatch(
                      bulkUpdateBookingGuest({
                        _id: bookingId,
                        bookingGuest: guest,
                      }),
                    );
                  }}
                >
                  Update Guests
                </Button> */}
              </div>
            </div>
            <p>
              THIS BOOKING {enabledEticket ? 'HAS' : 'DOES NOT HAVE'} eTICKETS
              <Link
                to={`/etickets/tickets/${bookingId}`}
                className={
                  enabledEticket
                    ? 'custom_text_hover text-decoration-underline mx-1'
                    : 'custom_text_hover mx-1'
                }
                target="_blank"
              >
                DIRECTORY BROWSING
              </Link>
              ENABLED -
              <span
                className="custom_text_hover text-decoration-underline mx-1"
                onClick={() => {
                  setEnabledEticket(!enabledEticket);
                }}
              >
                {enabledEticket
                  ? 'CLICK HERE TO DISABLE'
                  : 'CLICK HERE TO ENABLE'}
              </span>
            </p>
            <p>
              <span
                className="custom_text_hover text-decoration-underline"
                onClick={() => OpenResetRecreateETicket()}
              >
                RESET TICKET NUMBERS AND RECREATE ALL NAMED GUEST ETICKETS -
                THIS WILL DELETE ALL PREVIOUSLY CREATED ETICKETS
              </span>
            </p>
          </>
        ) : (
          'There are no guests assigned to this booking'
        )}
      </div>
      <AddGuestPopup
        CloseAddGuest={CloseAddGuest}
        addGuestPopup={addGuestPopup}
        editUser={editUser}
        OpenRebuidETicket={OpenRebuidETicket}
        OpenDeleteETicket={OpenDeleteETicket}
      />
      {/* <Dialog
        aria-labelledby="CancelBooking-title"
        open={openPopUp}
        className="delete_popup"
      >
        <BootstrapDialogTitle
          id="CancelBooking-title"
          onClose={ClosePopUp}
        ></BootstrapDialogTitle>
        <DialogContent dividers>
          <div className="popup_content_wrap">
            <div className="delete_popup_wrap">
              <h2 className="mb-3">Recreate Tickets</h2>
              <p>
                Are you sure you want to recreate all eTickets - this will
                renumber all the tickets so any tickets already sent out will be
                incorrect. This will take some time.?
              </p>
              <ul className="d-flex align-items-center justify-content-center">
                <li>
                  <Button className="btn_border mx-2" onClick={ClosePopUp}>
                    Cancel
                  </Button>
                </li>
                <li>
                  <Button
                    className="btn_primary mx-2"
                    onClick={() => {
                      HandleChange();
                    }}
                  >
                    Ok
                  </Button>
                </li>
              </ul>
            </div>
          </div>
        </DialogContent>
      </Dialog> */}
      <DeletePopupModal
        CloseDelete={CloseGuestDelete}
        deletePopup={deleteGuestPopup}
        onClickDelete={deleteGuestListData}
        ok={
          deleteGuestId?.deleted === false
            ? `Delete`
            : deleteGuestId?.deleted
            ? `ok`
            : ''
        }
        name={
          deleteGuestId?.deleted === false
            ? `Are you sure you want to delete this guest?`
            : deleteGuestId?.deleted
            ? `Are you sure you want to re-activate this guest?`
            : ''
        }
      />
      <DeletePopupModal
        CloseDelete={CloseRebuidETicket}
        deletePopup={rebuildPopup}
        onClickDelete={rebuildETicketListData}
        ok="ok"
        name="Are you sure you want to recreate named eTickets for this guest?"
      />

      <DeletePopupModal
        CloseDelete={CloseDeleteETicket}
        deletePopup={deleteETicketPopup}
        onClickDelete={deleteEticketListData}
        name="Are you sure you want to DELETE the eTicket file for this guest?"
      />

      <DeletePopupModal
        CloseDelete={CloseResetRecreateETicket}
        deletePopup={recreatePopup}
        onClickDelete={resetRecreateETicketEticket}
        ok="ok"
        name="Are you sure you want to recreate all eTickets - this will renumber all the tickets so any tickets already sent out will be incorrect. This will take some time.?"
      />
    </div>
  );
}
